<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import GameImage from './GameImage.vue'
import ItemFacts from './ItemFacts.vue'
import Modal from './Modal.vue'
const props=defineProps<{detail:any,locked?:boolean}>()
const emit=defineEmits<{section:[id:string],support:[value:{case_id?:string,uid:number}]}>()
const selected=ref<any>(null)
const selectedSection=ref('equipment')
watch(()=>props.detail.character.charac_no,()=>{selected.value=null})
const names=['武器','称号','上衣','头肩','下装','鞋','腰带','项链','手镯','戒指','辅助装备','魔法石']
const equipment=computed(()=>names.map((name,slot)=>({...props.detail.equipment?.items?.find((item:any)=>item.slot===slot),slot,slot_label:name})))
const backpack=computed(()=>props.detail.backpack_summary??{state:props.detail.backpack?.state??'unknown',occupied_slots:props.detail.backpack?.items?.length,slot_count:props.detail.backpack?.slot_count,items:props.detail.backpack?.items?.slice(0,6)??[]})
const support=computed(()=>props.detail.support_summary??{state:'unknown',items:[]})
const mail=computed(()=>props.detail.mail_summary??{state:'unknown'})
const number=(value:unknown)=>value==null?'未知':Number(value).toLocaleString('zh-CN')
</script>
<template><div class="character-overview" data-testid="character-overview">
 <dl class="overview-resources"><div><dt>角色携带金币</dt><dd>{{number(detail.wealth?.gold)}}</dd><small>{{detail.wealth?.state==='ok'?'不含仓库金币、点券或代币券':'金币存档缺失，不能视为0'}}</small></div><div><dt>普通疲劳已消耗 / 上限</dt><dd>{{number(detail.play_state?.fatigue??detail.character.fatigue)}} <span>/ {{number(detail.character.max_fatigue)}}</span></dd><button :disabled="locked" @click="emit('section','fatigue')">恢复疲劳 →</button></div><div><dt>最近角色存档</dt><dd class="overview-save-time">{{detail.play_state?.last_play_time||detail.character.last_play_time||'未记录'}}</dd><small>存档值，在线变化可能尚未保存</small></div></dl>
 <div class="overview-main-grid"><section class="overview-panel overview-equipment"><div class="section-title"><h3>穿戴装备 <small>12 个存档槽位</small></h3><button :disabled="locked" @click="emit('section','equipment')">全部装备 →</button></div><div v-if="detail.equipment?.state==='ok'" class="overview-equipment-grid"><button v-for="item in equipment" :key="item.slot" type="button" :disabled="!item.id" :class="{'is-empty':!item.id}" :aria-label="item.slot_label+'：'+(item.name||'空槽位')" @click="selected=item;selectedSection='equipment'"><GameImage v-if="item.id" :image="item.image" :label="item.name" :rarity-name="item.rarity_name" :rarity="item.rarity"/><span v-else class="overview-empty-slot">＋</span><span class="overview-slot-copy"><small>{{item.slot_label}}</small><strong>{{item.name||'空槽位'}}</strong></span><b v-if="item.enhancement" class="overview-enhancement">+{{item.enhancement}}</b></button></div><p v-else class="field-hint">{{detail.equipment?.message||'穿戴装备存档暂不可用。'}}</p><p class="overview-panel-note">点击装备查看已知属性；实际维护需要单独预览确认。</p></section>
 <section class="overview-panel overview-backpack"><div class="section-title"><h3>背包摘要</h3><button :disabled="locked" @click="emit('section','backpack')">打开背包 →</button></div><div class="overview-backpack-count"><strong>{{number(backpack.occupied_slots)}}</strong><span>个非空槽位</span><small v-if="backpack.slot_count!=null">/ {{number(backpack.slot_count)}} 个存档槽位</small></div><div v-if="backpack.state==='ok'" class="overview-backpack-items"><button v-for="item in backpack.items" :key="item.slot" type="button" :aria-label="'查看背包物品 '+item.name" @click="selected=item;selectedSection='backpack'"><GameImage :image="item.image" :label="item.name" :rarity-name="item.rarity_name" :rarity="item.rarity"/><span>{{item.name}}</span><small>×{{number(item.quantity)}}</small></button><p v-if="!backpack.occupied_slots" class="field-hint">没有非空物品存档。</p></div><p v-else class="field-hint">背包存档暂不可用，不能视为空背包。</p><p class="overview-panel-note">摘要只展示前 6 件；存档槽数不代表已开放格数。</p></section></div>
 <div class="overview-followup-grid"><section class="overview-panel"><div class="section-title"><h3>待处理玩家问题 <span v-if="support.state==='ok'" class="pill">{{number((support.open_count??0)+(support.in_progress_count??0))}}</span></h3><button :disabled="locked" @click="emit('support',{uid:detail.character.uid})">全部问题 →</button></div><template v-if="support.state==='ok'"><button v-for="item in support.items" :key="item.case_id" class="overview-case" :disabled="locked" @click="emit('support',{uid:detail.character.uid,case_id:item.case_id})"><span><strong>{{item.title}}</strong><small>{{item.scope==='account'?'账号问题':'当前角色'}} · {{item.status==='in_progress'?'处理中':'待处理'}}</small></span><span aria-hidden="true">→</span></button><p v-if="!support.items?.length" class="field-hint">暂无待处理问题。</p></template><p v-else class="field-hint">问题摘要暂不可用，可打开问题列表查询。</p></section>
 <section class="overview-panel"><div class="section-title"><h3>邮件与后续处理</h3><button :disabled="locked" @click="emit('section','mail')">查看邮件 →</button></div><div v-if="mail.state==='ok'" class="overview-mail-state"><strong>{{number(mail.unclaimed_marker)}}</strong><span>近期附件含未领取标记</span><small>核对最近 {{number(mail.checked_attachments)}} 条后台投递附件；不是全邮箱数量或客户端领取证明。</small></div><p v-else class="field-hint">暂无可用邮件摘要，可按原投递记录查询。</p><div class="overview-maintenance-links"><button :disabled="locked" @click="emit('section','rescue')">位置救援</button><button :disabled="locked" @click="emit('section','quests')">任务排查</button><button :disabled="locked" @click="emit('section','unlock')">装备解锁</button><button :disabled="locked" @click="emit('section','activity')">管理记录</button></div></section></div>
 <Teleport to="body"><Modal v-if="selected" :title="'物品存档 · #'+selected.id" drawer @close="selected=null"><ItemFacts :item="selected" stored/><template #footer><button type="button" class="primary" @click="selected=null">关闭详情</button><button type="button" :disabled="locked" @click="selected=null;emit('section',selectedSection)">{{selectedSection==='backpack'?'前往背包':'前往穿戴装备'}}</button></template></Modal></Teleport>
</div></template>
<style scoped>
