ont-weight:500}.is-empty .overview-slot-copy strong{color:var(--text-tertiary)}.overview-empty-slot{width:32px;flex:none;color:var(--text-tertiary);font-size:20px;font-weight:300}.overview-enhancement{font-size:10px;color:var(--primary-color);margin-left:auto}.overview-panel-note{font-size:10px;line-height:1.6;color:var(--text-secondary);margin:12px 0 0}.overview-backpack-count{display:flex;gap:7px;align-items:baseline;font-size:12px;margin:0 0 12px}.overview-backpack-count strong{font-size:24px}.overview-backpack-count small{color:var(--text-secondary);font-size:10px}.overview-backpack-items{display:grid;grid-template-columns:1fr 1fr;gap:8px}.overview-backpack-items>button{display:grid;grid-template-columns:32px minmax(0,1fr);gap:2px 8px;padding:6px;background:var(--bg-secondary);min-width:0;border:0;border-radius:5px;text-align:left;justify-items:start}.overview-backpack-items :deep(.game-image){grid-row:1/3;width:32px;height:32px}.overview-backpack-items>button>span{width:100%;font-size:11px;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.overview-backpack-items small{font-size:10px;color:var(--text-secondary)}.overview-followup-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.overview-case{display:flex;width:100%;gap:12px;align-items:center;justify-content:space-between;padding:10px 0;text-align:left;border:0;border-bottom:1px solid var(--border-color);border-radius:0;background:transparent}.overview-case strong,.overview-case small{display:block}.overview-case strong{font-size:12px;font-weight:500}.overview-case small{font-size:10px;margin-top:4px;color:var(--text-secondary)}.overview-mail-state{display:grid;grid-template-columns:auto 1fr;align-items:center;gap:4px 10px;font-size:12px}.overview-mail-state>strong{font-size:27px;font-weight:650}.overview-mail-state small{grid-column:1/-1;font-size:10px;line-height:1.7;color:var(--text-secondary)}.overview-maintenance-links{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}.overview-maintenance-links>button{padding:5px 8px;font-size:11px;border:1px solid var(--border-color);background:transparent}
@media(max-width:1100px){.overview-main-grid{grid-template-columns:1fr}.overview-equipment-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}
@media(max-width:700px){.character-overview{gap:12px}.overview-resources{grid-template-columns:1fr 1fr;gap:8px}.overview-resources>div{padding:10px 12px}.overview-resources>div:last-child{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:8px}.overview-resources>div:last-child>small{display:none}.overview-resources dt{font-size:10px}.overview-resources dd{font-size:20px}.overview-resources .overview-save-time{font-size:11px;margin:0}.overview-panel{padding:12px}.overview-equipment-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:5px}.overview-equipment-grid>button{height:57px;padding:5px;gap:4px}.overview-slot-copy strong{font-size:10px}.overview-equipment-grid :deep(.game-image){min-width:27px;width:27px;height:27px}.overview-enhancement{position:absolute;right:3px;top:2px;font-size:9px}.overview-equipment-grid>button{position:relative}.overview-followup-grid{grid-template-columns:1fr;gap:12px}.overview-panel .section-title{margin-bottom:10px}.overview-panel h3>small{display:none}}
</style>
